    )) USING utf8mb4);

    DROP TEMPORARY TABLE IF EXISTS tmp_master_lines;
    CREATE TEMPORARY TABLE tmp_master_lines (
        raw_category VARCHAR(255) NOT NULL,
        raw_subcategory VARCHAR(255) NOT NULL,
        raw_line VARCHAR(255) NOT NULL
    );

    SET master_lines_text = master_lines_json;
    SET master_lines_text = TRIM(BOTH '[' FROM master_lines_text);
    SET master_lines_text = TRIM(BOTH ']' FROM master_lines_text);
    SET master_lines_text = REPLACE(master_lines_text, '],[', row_sep);
    SET master_lines_text = REPLACE(master_lines_text, '\",\"', field_sep);
    SET master_lines_text = REPLACE(master_lines_text, '[\"', '');
    SET master_lines_text = REPLACE(master_lines_text, '\"]', '');

    WHILE master_lines_text IS NOT NULL AND master_lines_text <> '' DO
        SET row_pos = LOCATE(row_sep, master_lines_text);

        IF row_pos = 0 THEN
            SET current_row = master_lines_text;
            SET master_lines_text = '';
        ELSE
            SET current_row = LEFT(master_lines_text, row_pos - 1);
            SET master_lines_text = SUBSTRING(master_lines_text, row_pos + 1);
        END IF;

        SET field_pos = LOCATE(field_sep, current_row);
        SET current_field = LEFT(current_row, field_pos - 1);
        SET current_category = TRIM(BOTH '\"' FROM current_field);
        SET current_row = SUBSTRING(current_row, field_pos + 1);

        SET field_pos = LOCATE(field_sep, current_row);
        SET current_field = LEFT(current_row, field_pos - 1);
        SET current_subcategory = TRIM(BOTH '\"' FROM current_field);
        SET current_row = SUBSTRING(current_row, field_pos + 1);

        SET current_line = TRIM(BOTH '\"' FROM current_row);

        INSERT INTO tmp_master_lines (
            raw_category,
            raw_subcategory,
            raw_line
        )
        VALUES (
            current_category,
            current_subcategory,
            current_line
        );
    END WHILE;

    INSERT INTO Line (name, id_subcategory_fk, id_company_fk)
    SELECT src.canonical_line, s.id_subcategory, 1
    FROM (
        SELECT
            MIN(raw_rows.raw_line) AS canonical_line,
            LOWER(TRIM(raw_rows.raw_category)) AS normalized_category,
            LOWER(TRIM(raw_rows.raw_subcategory)) AS normalized_subcategory,
            LOWER(TRIM(raw_rows.raw_line)) AS normalized_line
        FROM tmp_master_lines AS raw_rows
        GROUP BY
            LOWER(TRIM(raw_rows.raw_category)),
            LOWER(TRIM(raw_rows.raw_subcategory)),
            LOWER(TRIM(raw_rows.raw_line))
    ) AS src
    JOIN Category c
        ON LOWER(TRIM(c.name)) = src.normalized_category
    JOIN Subcategory s
        ON LOWER(TRIM(s.name)) = src.normalized_subcategory
       AND s.id_category_fk = c.id_category
    LEFT JOIN Line l
        ON l.id_company_fk = 1
       AND LOWER(TRIM(l.name)) = src.normalized_line
    WHERE l.id_line IS NULL;

    DROP TEMPORARY TABLE IF EXISTS tmp_master_lines;
END //

DELIMITER ;

CALL sp_seed_master_lines();

